#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The three set-up entries only the owner can give the books:
#   setup-wizard.sh            GST registration, the company's address and the
#                              holiday list, then one check-and-save at the end
#   setup-wizard.sh --dry-run  the whole walk; the last step lets the books check
#                              everything, then undoes it, so nothing is saved
#   setup-wizard.sh --status   what the books hold now, then exit
# The books' side is wizard_books.py, run inside the bench as wire.sh runs its
# scripts. A part already filled in is kept unless the owner says to change it.

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
ENV_FILE=/dev/null   # nothing goes to a .env file: every answer goes to the books
BENCH_DIR="$(. "$HERE/lib.sh" && printf '%s' "$BENCH_DIR")"
SITE="$(. "$HERE/lib.sh" && printf '%s' "$SITE")"
LOG_FILE="$(. "$HERE/lib.sh" && printf '%s' "$LOG_DIR")/books-setup-wizard.log"
DRY_RUN=0
PASS=0      # how many times the owner has walked stages 2 to 4
GSTIN=""; NEW_LINES=""
YEAR="$(date +%Y)"
NEXT_YEAR=$((YEAR + 1))

# books ARGS runs the helper inside the bench; its noise goes to the log.
books() {
  mkdir -p "$(dirname "$LOG_FILE")"
  (cd "$BENCH_DIR/sites" && "$BENCH_DIR/env/bin/python" "$HERE/wizard_books.py" "$@") 2>>"$LOG_FILE"
}
# plain ARGS runs the helper's checks that need no books.
plain() { /usr/bin/python3 -I "$HERE/wizard_books.py" "$@"; }

# jget JSON KEY[.KEY] prints one value; a list prints one item per line.
jget() {
  /usr/bin/python3 -I -c 'import json, sys
d = json.loads(sys.argv[1])
for k in sys.argv[2].split("."):
    d = d.get(k) if isinstance(d, dict) else None
if isinstance(d, list):
    print("\n".join(" ".join(x) if isinstance(x, list) else str(x) for x in d))
elif d is not None:
    print(d)' "$1" "$2"
}

# no_more_input: the terminal closed mid-answer.
no_more_input() { printf '\n'; warn "No more input. Nothing was saved."; exit 1; }

# ask_or KEY "Prompt" [default] reads a visible value; Enter takes the default.
ask_or() {
  local key="$1" prompt="$2" def="${3:-}" input="" s=$'\001' e=$'\002' p
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$def" ]] && p+="$s$DIM$e[Enter: $def]$s$RESET$e "
  read -e -r -p "$p" input || [[ -n "$input" ]] || no_more_input
  [[ -z "$input" ]] && input="$def"
  printf -v "$key" '%s' "$input"
}

# yes_no "Question" y|n: success on yes; Enter takes the default.
yes_no() {
  local reply="" hint="[y/N]"
  [[ "$2" == y ]] && hint="[Y/n]"
  printf '  %s? %s %s%s ' "$YELLOW" "$1" "$hint" "$RESET"
  read -r reply || [[ -n "$reply" ]] || no_more_input
  [[ -z "$reply" ]] && reply="$2"
  [[ "$reply" =~ ^[Yy] ]]
}

# match_state TEXT prints the books' own spelling of a state, or nothing.
match_state() {
  /usr/bin/python3 -I -c 'import sys
want = " ".join(sys.argv[1].split()).lower()
for s in sys.argv[2].splitlines():
    if s.lower() == want:
        print(s)' "$1" "$STATES"
}

books_ready() {
  if [[ ! -d "$BENCH_DIR/sites/$SITE" ]]; then
    warn "The books are not installed on this Mac yet. Run engine/books/install.sh first."
    exit 1
  fi
  if ! "$HERE/status.sh" >/dev/null 2>&1; then
    warn "The books are not on. Run: engine/bin/engine start"
    say "Then run this wizard again."
    exit 1
  fi
}

show_status() {
  books_ready
  books --status || { warn "The books did not answer. Details are in $LOG_FILE"; exit 1; }
}

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage_intro() {
  stage "What this does"
  say "Three things only you know go into the company's books:"
  step "whether the company is registered for GST, and its GST number"
  step "the company's address"
  step "the days the company is closed: weekly days off and public holidays"
  say "The books are on this Mac. Nothing is sent anywhere, and nothing is"
  say "saved until the last step, after you have checked it all."
  (( DRY_RUN )) && note "Dry run: the last step lets the books check everything, then undoes it."
  say ""
  books_ready
  STATUS_JSON="$(books --status --json)" || { warn "The books did not answer. Details are in $LOG_FILE"; exit 1; }
  COMPANY="$(jget "$STATUS_JSON" company)"
  STATES="$(jget "$STATUS_JSON" states)"
  CUR_GSTIN="$(jget "$STATUS_JSON" gstin)"
  CUR_CATEGORY="$(jget "$STATUS_JSON" gst_category)"
  CUR_GST_STATE="$(jget "$STATUS_JSON" gst_state)"
  CUR_LINE1="$(jget "$STATUS_JSON" address.line1)"
  CUR_LINE2="$(jget "$STATUS_JSON" address.line2)"
  CUR_CITY="$(jget "$STATUS_JSON" address.city)"
  CUR_STATE="$(jget "$STATUS_JSON" address.state)"
  CUR_PIN="$(jget "$STATUS_JSON" address.pincode)"
  CUR_PHONE="$(jget "$STATUS_JSON" address.phone)"
  CUR_EMAIL="$(jget "$STATUS_JSON" address.email)"
  CUR_LIST="$(jget "$STATUS_JSON" holiday_list.name)"
  CUR_OFFS="$(jget "$STATUS_JSON" holiday_list.weekly_offs)"
  CUR_PUBLIC="$(jget "$STATUS_JSON" holiday_list.public)"
  LEAVE_LIST="$(jget "$STATUS_JSON" leave_holiday_list)"
  say "What the books hold now for $COMPANY:"
  plain --show "$STATUS_JSON" | while IFS= read -r line; do note "  $line"; done
  pause
}

# ── Stage 2 ────────────────────────────────────────────────────────────────
# Sets GST_KEEP (1 keeps the books as they are), GST_REGISTERED, GSTIN,
# GST_STATE and SCHEME.
stage_gst() {
  stage "GST registration"
  local typed result last_gstin="${GSTIN:-$CUR_GSTIN}"
  GST_KEEP=0; GST_REGISTERED=0; GSTIN=""; GST_STATE=""; SCHEME=""
  if [[ -n "$CUR_GSTIN" ]]; then
    say "The books say the company is registered: GST number $CUR_GSTIN ($CUR_GST_STATE)."
    if ! confirm "Change it?"; then
      GST_KEEP=1; GST_REGISTERED=1; GSTIN="$CUR_GSTIN"; GST_STATE="$CUR_GST_STATE"
      return 0
    fi
  fi
  if ! yes_no "Is the company registered for GST?" "$([[ -n "$CUR_GSTIN" ]] && echo y || echo n)"; then
    say "Then the books keep it unregistered. Its invoices carry no GST number"
    say "and charge no GST. You can run this wizard again once it is registered."
    [[ -z "$CUR_GSTIN" ]] && GST_KEEP=1
    pause
    return 0
  fi
  GST_REGISTERED=1
  say "The GST number is on the registration certificate: 15 letters and digits."
  while :; do
    ask_or typed "GST number:" "$last_gstin"
    if result="$(books --check-gstin "$typed" --json)"; then
      GSTIN="$(jget "$result" gstin)"; GST_STATE="$(jget "$result" state)"
      say "That number is well formed. It belongs to $GST_STATE."
      break
    fi
    if [[ -n "$result" ]]; then warn "$(jget "$result" reason)"
    else warn "The books did not answer. Details are in $LOG_FILE"; fi
    say "Type it again."
  done
  say "Most companies use the Regular scheme. Composition is a simpler scheme"
  say "for small businesses; your registration certificate says which one."
  local def=Regular
  [[ "$CUR_CATEGORY" == "Registered Composition" ]] && def=Composition
  while :; do
    ask_or SCHEME "Regular or Composition?" "$def"
    case "$SCHEME" in
      [Rr]*) SCHEME=Regular; break ;;
      [Cc]*) SCHEME=Composition; break ;;
    esac
    warn "Type Regular or Composition."
  done
  if [[ "$GSTIN" == "$CUR_GSTIN" && "Registered $SCHEME" == "$CUR_CATEGORY" ]]; then GST_KEEP=1; fi
  pause
}

# ── Stage 3 ────────────────────────────────────────────────────────────────
# Sets ADDR_KEEP and LINE1 LINE2 CITY STATE PIN PHONE EMAIL.
stage_address() {
  stage "Company address"
  ADDR_KEEP=0
  if (( PASS == 1 )); then   # on a second pass, the answers typed last time are the defaults
    LINE1="$CUR_LINE1"; LINE2="$CUR_LINE2"; CITY="$CUR_CITY"; STATE="$CUR_STATE"
    PIN="$CUR_PIN"; PHONE="$CUR_PHONE"; EMAIL="$CUR_EMAIL"
  fi
  if [[ -n "$CUR_LINE1" ]]; then
    say "The books have this address:"
    note "  $CUR_LINE1${CUR_LINE2:+, $CUR_LINE2}, $CUR_CITY, $CUR_STATE $CUR_PIN"
    if [[ -n "$GST_STATE" && "$GST_STATE" != "$CUR_STATE" ]]; then
      warn "The GST number belongs to $GST_STATE, so the address must be in $GST_STATE too."
    elif ! confirm "Change it?"; then
      ADDR_KEEP=1
      return 0
    fi
  else
    say "The books have no address for the company yet. It goes on invoices."
  fi
  note "Type - to leave an optional line empty."
  while :; do
    ask_or LINE1 "Address line 1:" "$LINE1"
    [[ -n "${LINE1// /}" ]] && break
    warn "The first line is needed."
  done
  ask_or LINE2 "Address line 2 (optional):" "$LINE2"
  [[ "$LINE2" == "-" ]] && LINE2=""
  while :; do
    ask_or CITY "City:" "$CITY"
    [[ -n "${CITY// /}" ]] && break
    warn "The city is needed."
  done
  if [[ -n "$GST_STATE" ]]; then
    say "With a GST number, the address must be in the state the number belongs to: $GST_STATE."
  fi
  local typed found
  while :; do
    ask_or typed "State:" "${GST_STATE:-$STATE}"
    found="$(match_state "$typed")"
    if [[ -z "$found" ]]; then
      warn "\"$typed\" is not a state the books know. Write it in full, like Karnataka or Tamil Nadu."
    elif [[ -n "$GST_STATE" && "$found" != "$GST_STATE" ]]; then
      warn "The GST number belongs to $GST_STATE, so the address must be in $GST_STATE."
    else
      STATE="$found"; break
    fi
  done
  while :; do
    ask_or typed "PIN code:" "$PIN"
    if found="$(plain --check-pincode "$typed")"; then PIN="$found"; break; fi
    warn "$found"
  done
  ask_or PHONE "Phone (optional):" "$PHONE"
  [[ "$PHONE" == "-" ]] && PHONE=""
  while :; do
    ask_or typed "Email (optional):" "$EMAIL"
    [[ "$typed" == "-" ]] && typed=""
    if [[ -z "$typed" || "$typed" == ?*@?*.?* ]]; then EMAIL="$typed"; break; fi
    warn "That does not look like an email address."
  done
  pause
}

# ── Stage 4 ────────────────────────────────────────────────────────────────
# Sets HOL_KEEP, OFFS (days, one per line) and NEW_LINES (one holiday per line).
stage_holidays() {
  stage "Holiday list"
  HOL_KEEP=0; OFFS=""
  if [[ -n "$NEW_LINES" ]]; then
    say "The public holidays you typed last time:"
    printf '%s\n' "$NEW_LINES" | while IFS= read -r l; do note "  $l"; done
    yes_no "Keep them?" y || NEW_LINES=""
  fi
  local name="$COMPANY holidays $YEAR-$NEXT_YEAR"
  if [[ -n "$CUR_LIST" ]]; then
    say "The books have the holiday list $CUR_LIST."
    say "Weekly days off: $(printf '%s' "$CUR_OFFS" | tr '\n' ',' | sed 's/,$//; s/,/, /g')"
    [[ -n "$CUR_PUBLIC" ]] && { say "Public holidays:"; printf '%s\n' "$CUR_PUBLIC" | while IFS= read -r l; do note "  $l"; done; }
    if [[ -n "$LEAVE_LIST" ]] && ! confirm "Change it or add holidays?"; then
      HOL_KEEP=1
      return 0
    fi
  fi
  say "Leave needs a list of the days the company is closed. This one is called"
  say "\"$name\" and runs from 1 January $YEAR to 31 December $NEXT_YEAR."
  say ""
  yes_no "Is Sunday a day off every week?" y && OFFS="Sunday"
  local def_sat=n day
  printf '%s\n' "$CUR_OFFS" | grep -qx Saturday && def_sat=y
  yes_no "Is Saturday a day off every week?" "$def_sat" && OFFS="$OFFS"$'\n'"Saturday"
  for day in Monday Tuesday Wednesday Thursday Friday; do
    if printf '%s\n' "$CUR_OFFS" | grep -qx "$day"; then
      yes_no "Is $day a day off every week?" y && OFFS="$OFFS"$'\n'"$day"
    fi
  done
  say ""
  say "Now the public holidays the company closes for, one per line, like:"
  note "  $YEAR-08-15 Independence Day"
  say "Press Enter on an empty line to finish. None is fine: you can add more"
  say "later by running this wizard again."
  [[ -n "$CUR_PUBLIC" ]] && note "The public holidays already in the list stay."
  local line checked
  while :; do
    line=""
    read -e -r -p "  > " line || [[ -n "$line" ]] || no_more_input
    [[ -z "${line// /}" ]] && break
    if checked="$(plain --check-holiday "$line" --year "$YEAR")"; then
      NEW_LINES="${NEW_LINES:+$NEW_LINES$'\n'}$checked"
      note "  added: $checked"
    else
      warn "$checked"
    fi
  done
  pause
}

# ── Stage 5 ────────────────────────────────────────────────────────────────
# Returns 1 when the owner wants to go back and change the answers.
stage_save() {
  stage "Check and save"
  if (( GST_KEEP && ADDR_KEEP && HOL_KEEP )); then
    say "Nothing to change. The books stay as they are."
    pause "Press Enter to finish"
    exit 0
  fi
  say "This is what goes into the books:"
  say ""
  if (( GST_KEEP )); then note "GST: kept as it is (${CUR_GSTIN:-not registered})"
  elif (( GST_REGISTERED )); then say "GST: registered, $SCHEME scheme, number $GSTIN ($GST_STATE)"
  else say "GST: not registered"; fi
  if (( ADDR_KEEP )); then note "Address: kept as it is"
  else
    say "Address: $LINE1${LINE2:+, $LINE2}, $CITY, $STATE $PIN"
    [[ -n "$PHONE$EMAIL" ]] && say "         ${PHONE:+phone $PHONE}${PHONE:+${EMAIL:+, }}${EMAIL:+email $EMAIL}"
  fi
  if (( HOL_KEEP )); then note "Holiday list: kept as it is"
  else
    say "Holiday list: $COMPANY holidays $YEAR-$NEXT_YEAR, 1 January $YEAR to 31 December $NEXT_YEAR"
    _offs="$(printf '%s' "${OFFS#$'\n'}" | tr '\n' ',' | sed 's/,/, /g')"
    say "  weekly days off: ${_offs:-none}"
    if [[ -n "$NEW_LINES" ]]; then
      say "  public holidays to add:"
      printf '%s\n' "$NEW_LINES" | while IFS= read -r l; do say "    $l"; done
    else
      say "  no public holidays to add"
    fi
  fi
  say ""
  local question="Save this to the books?"
  (( DRY_RUN )) && question="Let the books check this? (Dry run: nothing is saved.)"
  if ! confirm "$question"; then
    yes_no "Go back and change your answers?" y && return 1
    say "Nothing was saved."
    exit 0
  fi

  local dir answers out rc=0
  dir="$(mktemp -d "${TMPDIR:-/tmp}/books-setup.XXXXXX")"
  answers="$dir/answers.json"
  ( umask 077
    A_YEAR="$YEAR" A_GST_KEEP="$GST_KEEP" A_REG="$GST_REGISTERED" A_GSTIN="$GSTIN" A_SCHEME="$SCHEME" \
    A_ADDR_KEEP="$ADDR_KEEP" A_LINE1="$LINE1" A_LINE2="$LINE2" A_CITY="$CITY" A_STATE="$STATE" \
    A_PIN="$PIN" A_PHONE="$PHONE" A_EMAIL="$EMAIL" A_HOL_KEEP="$HOL_KEEP" A_OFFS="$OFFS" A_LINES="$NEW_LINES" \
    /usr/bin/python3 -I -c 'import json, os
e = os.environ.get
gst = None
if e("A_GST_KEEP") != "1":
    gst = {"registered": e("A_REG") == "1", "gstin": e("A_GSTIN"), "category": e("A_SCHEME") or "Regular"}
address = None
if e("A_ADDR_KEEP") != "1":
    address = {k: e("A_" + k.upper(), "") for k in ("line1", "line2", "city", "state", "pin", "phone", "email")}
    address["pincode"] = address.pop("pin")
holidays = None
if e("A_HOL_KEEP") != "1":
    holidays = {"weekly_offs": [d for d in e("A_OFFS", "").splitlines() if d],
                "lines": [l for l in e("A_LINES", "").splitlines() if l]}
print(json.dumps({"year": int(e("A_YEAR")), "gst": gst, "address": address, "holidays": holidays}))' > "$answers"
  ) || { rm -rf "$dir"; warn "The answers could not be written down. Nothing was saved."; exit 1; }
  say "Asking the books..."
  if (( DRY_RUN )); then out="$(books --apply "$answers" --dry-run)" || rc=$?
  else out="$(books --apply "$answers")" || rc=$?; fi
  rm -rf "$dir"

  if (( rc != 0 )); then
    say ""
    if [[ -n "$out" ]]; then
      printf '%s\n' "$out" | while IFS= read -r l; do warn "$l"; done
    else
      warn "The books did not answer. Nothing was saved. Details are in $LOG_FILE"
    fi
    yes_no "Go back and change your answers?" y && return 1
    exit 1
  fi

  if (( DRY_RUN )); then
    say ""
    printf '%s\n' "$out" | while IFS= read -r l; do say "$l"; done
    pause "Press Enter to finish"
    return 0
  fi

  local now
  now="$(books --status)" || now="(The books did not answer the read-back. Run: engine/books/setup-wizard.sh --status)"
  finish
  say "The books now hold:"
  printf '%s\n' "$now" | while IFS= read -r l; do note "  $l"; done
  say ""
  say "What this changes for you:"
  if (( ! GST_KEEP )) && (( GST_REGISTERED )); then
    step "Invoices carry your GST number and show GST as taxable, no longer Nil-Rated."
  elif (( ! GST_KEEP )); then
    step "Invoices carry no GST number: the books treat the company as unregistered."
  fi
  (( ADDR_KEEP )) || step "Invoices and other papers show the company's address."
  (( HOL_KEEP )) || step "Leave can now be made final: the books know which days the company is closed."
  say ""
  return 0
}

run_setup() {

TOTAL_STAGES=5

# The library's banner speaks of a browser; this wizard has none, so it opens with its own frame.
_clear
printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "Finish setting up the books" "$RESET"
printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
printf '%s  This wizard asks you a few questions and writes your answers into the\n' "$DIM"
printf '  books on this Mac. Stop any time with Ctrl-C: nothing is saved until the\n'
printf '  last step, after you have checked it all.%s\n' "$RESET"
pause "Ready to start?"

stage_intro
while :; do
  _STAGE_INDEX=1; PASS=$((PASS + 1))
  stage_gst
  stage_address
  stage_holidays
  stage_save && break
done
}

run_wizard() {
  case "${1:-}" in
    --status) show_status ;;
    "") run_setup ;;
    --dry-run) DRY_RUN=1; run_setup ;;
    *) echo "Usage: engine/books/setup-wizard.sh [--dry-run | --status]" >&2; exit 64 ;;
  esac
}

run_wizard "$@"; exit
